INSERT INTO uji_organoleptik (id_menu, tanggal, warna, aroma, rasa, tekstur, keterangan) VALUES (3, '2026-04-08', 5, 5, 5, 5, 'Daging sangat empuk, bumbu meresap sempurna, sup bayam segar dan jernih, higienitas terjaga 100%.');
